    "abstract": "HMAC-ın rəsmi RFC spesifikasiyası. Bu sənəd HMAC alqoritminin tam təsvirini, ipad (0x36) və opad (0x5C) sabitlərinin seçilmə səbəblərini, açarın uzunluğu ilə bağlı tövsiyələri və təhlükəsizlik mülahizələrini əhatə edir. RFC 2104 HMAC-ın internet protokollarında standartlaşdırılmasının əsasını təşkil edir.",
